dashboard.definition:
{
  "title": "Claude Code Overview",
  "description": "At-a-glance Claude Code activity: tokens, cost, cache, tools, sessions",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_timerange": {
      "type": "input.timerange",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@d,now"
      },
      "title": "Time Range"
    }
  },
  "dataSources": {
    "ds_base_time": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | timechart sum(input_tokens) as input_tokens, sum(output_tokens) as output_tokens, sum(cache_read_tokens) as cache_read_tokens, sum(cache_creation_tokens) as cache_creation_tokens, sum(total_tokens) as total_tokens, sum(cost_usd) as cost_usd, count as messages"
      },
      "name": "Base: Metrics Over Time"
    },
    "ds_kpi_messages": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(messages) as count | fields count"
      },
      "name": "KPI Messages"
    },
    "ds_kpi_tokens": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(total_tokens) as count | eval count=tostring(count, \"commas\") | fields count"
      },
      "name": "KPI Tokens"
    },
    "ds_kpi_cost": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(cost_usd) as count | eval count=\"$\".tostring(round(count, 2), \"commas\") | fields count"
      },
      "name": "KPI Cost"
    },
    "ds_kpi_cache": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(input_tokens) as i, sum(cache_read_tokens) as cr, sum(cache_creation_tokens) as cc | eval count=if(i+cr+cc>0, round(cr/(i+cr+cc)*100, 1).\"%\", \"n/a\") | fields count"
      },
      "name": "KPI Cache Hit"
    },
    "ds_tokens_time": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| fields _time, input_tokens, output_tokens | rename input_tokens as \"Input Tokens\", output_tokens as \"Output Tokens\""
      },
      "name": "Tokens Over Time"
    },
    "ds_cost_time": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| fields _time, cost_usd | rename cost_usd as \"Cost (USD)\""
      },
      "name": "Cost Over Time"
    },
    "ds_cache_time": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| eval \"Cache Hit %\"=if(input_tokens+cache_read_tokens+cache_creation_tokens>0, round(cache_read_tokens/(input_tokens+cache_read_tokens+cache_creation_tokens)*100, 1), null()) | fields _time, \"Cache Hit %\""
      },
      "name": "Cache Hit Over Time"
    },
    "ds_base_model_time": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | timechart count by model"
      },
      "name": "Base: Messages by Model Over Time"
    },
    "ds_model_pie": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_model_time",
        "query": "| untable _time model count | stats sum(count) as count by model | sort - count"
      },
      "name": "Model Distribution"
    },
    "ds_base_stop": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | stats count by stop_reason | sort - count"
      },
      "name": "Base: Stop Reasons"
    },
    "ds_base_session": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | stats count as messages, sum(total_tokens) as tokens, sum(cost_usd) as cost, values(model) as models, latest(cwd) as project by sessionId"
      },
      "name": "Base: Per-Session Stats"
    },
    "ds_kpi_sessions": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_session",
        "query": "| stats count | fields count"
      },
      "name": "KPI Sessions"
    },
    "ds_top_sessions": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_session",
        "query": "| eval cost=round(cost, 4) | sort - cost | head 25 | rename sessionId as \"Session ID\", cost as \"Cost (USD)\", messages as \"Messages\", tokens as \"Total Tokens\", models as \"Models\", project as \"Project\""
      },
      "name": "Top Sessions by Cost"
    },
    "ds_proj_bar": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_session",
        "query": "| where isnotnull(project) | stats sum(messages) as count by project | sort - count | head 15 | rename project as \"Project\""
      },
      "name": "Activity by Project"
    },
    "ds_base_tools": {
      "type": "ds.search",
      "options": {
        "query": "`claude_assistant_events` | `dedup_messages` | `extract_tools` | stats count as calls by name | sort - calls"
      },
      "name": "Base: Tool Calls by Name"
    },
    "ds_kpi_tools": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_tools",
        "query": "| stats sum(calls) as count | fields count"
      },
      "name": "KPI Tool Calls"
    }
  },
  "visualizations": {
    "viz_kpi_messages": {
      "type": "splunk.singlevalue",
      "title": "Assistant Messages",
      "dataSources": {
        "primary": "ds_kpi_messages"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_sessions": {
      "type": "splunk.singlevalue",
      "title": "Unique Sessions",
      "dataSources": {
        "primary": "ds_kpi_sessions"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_tokens": {
      "type": "splunk.singlevalue",
      "title": "Total Tokens",
      "dataSources": {
        "primary": "ds_kpi_tokens"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_cost": {
      "type": "splunk.singlevalue",
      "title": "Est. Cost (USD)",
      "dataSources": {
        "primary": "ds_kpi_cost"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "cost_analysis"
          }
        }
      ]
    },
    "viz_kpi_cache": {
      "type": "splunk.singlevalue",
      "title": "Cache Hit %",
      "dataSources": {
        "primary": "ds_kpi_cache"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "cache_performance"
          }
        }
      ]
    },
    "viz_kpi_tools": {
      "type": "splunk.singlevalue",
      "title": "Tool Calls",
      "dataSources": {
        "primary": "ds_kpi_tools"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "tool_activity"
          }
        }
      ]
    },
    "viz_tokens_time": {
      "type": "splunk.area",
      "title": "Token Consumption Over Time",
      "dataSources": {
        "primary": "ds_tokens_time"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_model_time": {
      "type": "splunk.area",
      "title": "Messages by Model Over Time",
      "dataSources": {
        "primary": "ds_base_model_time"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_cost_time": {
      "type": "splunk.line",
      "title": "Cost Over Time",
      "dataSources": {
        "primary": "ds_cost_time"
      },
      "options": {}
    },
    "viz_cache_time": {
      "type": "splunk.line",
      "title": "Cache Hit % Over Time",
      "dataSources": {
        "primary": "ds_cache_time"
      },
      "options": {}
    },
    "viz_model_pie": {
      "type": "splunk.pie",
      "title": "Model Distribution",
      "dataSources": {
        "primary": "ds_model_pie"
      },
      "options": {},
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "token_usage",
            "tokens": [
              {
                "token": "form.model_tok",
                "value": "name.value"
              }
            ]
          }
        }
      ]
    },
    "viz_tool_pie": {
      "type": "splunk.pie",
      "title": "Tool Call Distribution",
      "dataSources": {
        "primary": "ds_base_tools"
      },
      "options": {},
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "tool_activity"
          }
        }
      ]
    },
    "viz_stop_pie": {
      "type": "splunk.pie",
      "title": "Stop Reasons",
      "dataSources": {
        "primary": "ds_base_stop"
      },
      "options": {}
    },
    "viz_proj_bar": {
      "type": "splunk.bar",
      "title": "Activity by Project",
      "dataSources": {
        "primary": "ds_proj_bar"
      },
      "options": {}
    },
    "viz_top_sessions": {
      "type": "splunk.table",
      "title": "Top Sessions by Cost",
      "dataSources": {
        "primary": "ds_top_sessions"
      },
      "options": {},
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "sessions",
            "tokens": [
              {
                "token": "form.session_tok",
                "value": "row.Session ID.value"
              }
            ]
          }
        }
      ]
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {"item": "viz_kpi_messages", "type": "block", "position": {"x": 0, "y": 0, "w": 200, "h": 120}},
      {"item": "viz_kpi_sessions", "type": "block", "position": {"x": 200, "y": 0, "w": 200, "h": 120}},
      {"item": "viz_kpi_tokens", "type": "block", "position": {"x": 400, "y": 0, "w": 200, "h": 120}},
      {"item": "viz_kpi_cost", "type": "block", "position": {"x": 600, "y": 0, "w": 200, "h": 120}},
      {"item": "viz_kpi_cache", "type": "block", "position": {"x": 800, "y": 0, "w": 200, "h": 120}},
      {"item": "viz_kpi_tools", "type": "block", "position": {"x": 1000, "y": 0, "w": 200, "h": 120}},
      {"item": "viz_tokens_time", "type": "block", "position": {"x": 0, "y": 120, "w": 600, "h": 300}},
      {"item": "viz_model_time", "type": "block", "position": {"x": 600, "y": 120, "w": 600, "h": 300}},
      {"item": "viz_cost_time", "type": "block", "position": {"x": 0, "y": 420, "w": 400, "h": 300}},
      {"item": "viz_cache_time", "type": "block", "position": {"x": 400, "y": 420, "w": 400, "h": 300}},
      {"item": "viz_model_pie", "type": "block", "position": {"x": 800, "y": 420, "w": 400, "h": 300}},
      {"item": "viz_tool_pie", "type": "block", "position": {"x": 0, "y": 720, "w": 400, "h": 300}},
      {"item": "viz_stop_pie", "type": "block", "position": {"x": 400, "y": 720, "w": 400, "h": 300}},
      {"item": "viz_proj_bar", "type": "block", "position": {"x": 800, "y": 720, "w": 400, "h": 300}},
      {"item": "viz_top_sessions", "type": "block", "position": {"x": 0, "y": 1020, "w": 1200, "h": 320}}
    ],
    "globalInputs": ["input_timerange"]
  }
}
